let adrIndexOnly = false;
let listingFailure: unknown;
try {
  const unmerged = runGit(worktree, ['ls-files', '--unmerged', '-z'], pinned);
  adrIndexOnly = ADR_INDEX_CONFLICT.test(unmerged.split('\0').filter(Boolean).join('\0'));
} catch (listing) {
  listingFailure = listing;
}
try {
  runGit(worktree, ['rebase', '--abort'], pinned);
} catch (aborting) {
  rethrowIfKilled(aborting);
  // nothing to abort — the rebase never started
}
// After the abort, so an interrupt leaves no stopped rebase behind and is
// never read as a stop the gate can merge past.
rethrowIfKilled(listingFailure);
rethrowIfKilled(error);
